E.append((6009716,'جئی کے چوکر (اوٹ برین) کے مفنز',
'یہ نرم، مزیدار مفنز ایک بہترین ناشتہ یا اسنیک بنتے ہیں۔ انہیں پاٹ لک برنچ یا صبح سویرے ٹیل گیٹ پر لے جائیں!',
'12','1 مفن',
['2 1/4 کپ جئی کا چوکر (اوٹ برین)','1/4 کپ بھوری چینی کا متبادل (مضبوطی سے بھرا ہوا)','1 کھانے کا چمچ بیکنگ پاؤڈر','1 1/2 چائے کا چمچ پسی ہوئی دار چینی','3/4 کپ سکم دودھ','1/4 کپ انڈے کا متبادل ((1 انڈے کے برابر))','2 کھانے کے چمچ کینولا تیل','1 کپ بغیر میٹھے کی سیب کی چٹنی (ایپل ساس)','1 درمیانا کیلا (مسلا ہوا)','2 کھانے کے چمچ خشک پھل جیسے کشمش، کھجور، خوبانی (اختیاری)'],
['اوون کو 425 ڈگری F پر پہلے سے گرم کریں۔','پہلے چار اجزاء کو ایک بڑے پیالے میں ملا لیں۔ ایک طرف رکھ دیں۔','دودھ، انڈا اور تیل ملا لیں۔ ایپل ساس کو مسلے ہوئے کیلے کے ساتھ ملائیں اور مائع اجزاء کے ساتھ ملا دیں۔ خشک اجزاء میں ڈالیں اور صرف نم ہونے تک ملائیں۔','نان اسٹک کوکنگ اسپرے کی ہوئی مفن ٹن میں ڈالیں۔ کاغذی لائنرز استعمال نہ کریں، کیونکہ مفنز کاغذ سے چپکنے کا رجحان رکھتے ہیں۔ 15-17 منٹ بیک کریں۔','مشورہ: کم چینی کی وجہ سے ان مفنز کے اوپری حصے اچھی طرح بھورے نہیں ہوتے، لیکن یہ پھر بھی نرم اور ذائقے سے بھرپور ہوتے ہیں!'],[]))
E.append((6010103,'بلگوگی (گرل کیا ہوا کوریائی گوشت)',
'اس گرل کیے ہوئے گوشت کا میرینیڈ بنانا بہت آسان ہے۔ اس ترکیب میں بیف ٹینڈرلوئن استعمال ہوتا ہے، جو کم چکنائی والا ٹکڑا ہے۔',
'4','3 اونس گوشت + 4 اونس سبزیاں',
['12 اونس کم چکنائی والا بغیر ہڈی بیف ٹینڈرلوئن','3 ڈنڈیاں ہری پیاز (اسکیلین) ((سفید اور ہرے حصے)، کٹی ہوئی)','2 لہسن کی پھانکیں (قیمہ کی ہوئی)','2 چائے کے چمچ رائس وائن سرکہ','2 کھانے کے چمچ پانی','3 کھانے کے چمچ کم سوڈیم والی سویا ساس','1 کھانے کا چمچ شہد یا 2 پیکٹ چینی کا متبادل','1/2 چائے کا چمچ کالی مرچ','1 (16 اونس) تھیلا منجمد اسٹر فرائی سبزیاں'],
['گوشت کو پلاسٹک ریپ میں لپیٹیں اور سخت ہونے تک (لیکن پتھر جیسا سخت نہیں) فریز کریں۔ سخت ہونے کے بعد گوشت کو پتلی لمبی پٹیوں میں کاٹ لیں۔ بیکنگ ڈش میں رکھیں۔','ایک چھوٹے پیالے میں ہری پیاز، لہسن، رائس وائن سرکہ، پانی، سویا ساس، میٹھا کرنے والا (شہد یا چینی کا متبادل) اور مرچ پھینٹ کر ملا لیں۔ مرکب کو گوشت پر ڈالیں اور فریج میں کم از کم 30 منٹ، زیادہ سے زیادہ 2 گھنٹے میرینیٹ ہونے دیں۔ جب گوشت میرینیٹ ہو رہا ہو، اندرونی یا بیرونی گرل پہلے سے گرم کریں۔','گوشت کو میرینیڈ سے نکالیں اور فاضل میرینیڈ جھاڑ دیں۔ گوشت کو ہر طرف 2-3 منٹ یا درمیانے سے زیادہ پکنے (مِیڈیم ویل) تک گرل کریں۔','سبزیوں کو بھاپ میں پکائیں اور گوشت کو بھاپ میں پکی سبزیوں کے اوپر رکھ کر پیش کریں۔'],[]))
E.append((6011738,'بھنے ہوئے آلو، گاجر اور پارسنپ',
'سبزیوں کو بھوننا ان کے قدرتی میٹھے ذائقے کو ابھارنے کا بہترین طریقہ ہے۔ یہ کرنا آسان ہے اور خزاں کی یہ تین سبزیاں ایک مزیدار مرکب بناتی ہیں۔',
'10','1/2 کپ',
['5 بڑی گاجریں (ہر ایک 2 3/4 اونس، چھلی ہوئی، سرے کٹے ہوئے، ترچھی کٹی ہوئی)','4 بڑی پارسنپ (ہر ایک 5 اونس، چھلی ہوئی، سرے کٹے ہوئے، ترچھی کٹی ہوئی)','2 درمیانی شکر قندی (ہر ایک 5 اونس، چھلی ہوئی، درمیانے چوکور ٹکڑوں میں کٹی ہوئی)','2 کھانے کے چمچ زیتون کا تیل','1 چائے کا چمچ کوشر نمک','2 کھانے کے چمچ تازہ جڑی بوٹیاں (تھائم، اوریگانو، سیج، یا روزمیری)','1/8 چائے کا چمچ کالی مرچ (تازہ پسی ہوئی)'],
['اوون کو 450 ڈگری F پر گرم کریں۔ ایک بڑے پیالے میں سبزیوں کو تیل، نمک اور جڑی بوٹیوں کے ساتھ ملائیں۔ لگانے کے لیے الٹ پلٹ کریں۔','سبزیوں کو پارچمنٹ کاغذ بچھی دو بیکنگ شیٹس پر ترتیب دیں۔ اندر سے نرم اور باہر سے بھورا ہونے تک بھونیں، تقریباً 20-30 منٹ۔ پکانے کے درمیان میں سبزیوں کو پلٹ دیں۔','گرم یا کمرے کے درجہ حرارت پر پیش کریں۔'],[]))
E.append((6012687,'موسمی بیک کی ہوئی سفید مچھلی کا پاؤچ',
'ورق (فوائل) یا پارچمنٹ کے پاؤچ سبزیوں کے ساتھ بالکل صحیح پکی ہوئی اور مسالہ لگی ہوئی مچھلی بنانے کا ایک آسان طریقہ ہیں۔ پاؤچ کے کناروں کو بند کرنے سے آپ ساری نمی اندر ہی بند کر لیتے ہیں۔ نتیجہ - پکانے کے بعد پاؤچ میں بہت سی مزیدار چٹنی، اور صفائی کا کوئی کام نہیں! بھاپ دیتی ہوئی مچھلی اور سبزیوں کو فارو یا براؤن رائس پر پیش کریں، یا اس ذائقہ دار چٹنی کو سالم اناج کے رول سے صاف کر لیں۔ اپنے کھانے کو ایک کرکرے سائیڈ سلاد کے ساتھ مکمل کریں۔',
'4','1 پاؤچ (4 اونس مچھلی + تقریباً 1 کپ سبزیاں)',
['4 کپ مختلف سبزیوں کی ڈنڈیاں (نوالے کے سائز کی غیر نشاستہ دار سبزیاں، جیسے بروکلی، شملہ مرچ، پیلا اسکواش اور توری)','6 چائے کے چمچ ایکسٹرا ورجن زیتون کا تیل (تقسیم شدہ)','1/2 چائے کا چمچ سمندری نمک (تقسیم شدہ)','16 اونس سفید مچھلی جیسے ہیلی بٹ یا کوڈ (4 (4 اونس) فلیٹس میں تقسیم کی ہوئی)','1 سالم شیلوٹ (باریک کٹا ہوا، تقسیم شدہ)','4 چائے کے چمچ لیموں کا رس (تقسیم شدہ)','1 چائے کا چمچ خشک جڑی بوٹیاں، جیسے روزمیری یا اوریگانو'],
['اوون کو 425° F پر پہلے سے گرم کریں۔ پارچمنٹ کاغذ یا ایلومینیم ورق کی ایک شیٹ کو 4 (12 انچ) چوکور ٹکڑوں میں کاٹ لیں۔','ہر چوکور ٹکڑے کے دائیں آدھے حصے پر ترتیب سے رکھیں: 1 کپ سبزیاں، 1½ چائے کا چمچ تیل، ایک چٹکی (تقریباً 1/16 چائے کا چمچ) نمک، 1 مچھلی کا فلیٹ، 1 کھانے کا چمچ شیلوٹ، 1 چائے کا چمچ لیموں کا رس، ¼ چائے کا چمچ جڑی بوٹیاں، اور ایک چٹکی نمک۔','ہر چوکور ٹکڑے کے بائیں حصے کو اجزاء کے اوپر موڑ دیں۔ کناروں کو اچھی طرح بند کریں۔ بیکنگ شیٹ پر رکھیں۔ 18 منٹ تک بیک کریں، یہاں تک کہ سبزیاں نرم ہو جائیں اور مچھلی ریشہ دار ہو جائے، اندرونی درجہ حرارت کم از کم 145° F ہو۔','مچھلی کو تقریباً 5 منٹ ٹھہرنے دیں، پھر پاؤچ احتیاط سے کھولیں اور پاؤچ کے اندر یا باہر نکال کر پیش کریں۔'],[]))
build(6,E)
